mapper.select:
SELECT *
FROM DAILYLOOKS
WHERE user_id = #{userId} 
AND IS_ACTIVE = 'Y' 
AND TO_CHAR(wear_date, 'YYYY-MM') = #{yearMonth}
ORDER BY wear_date ASC

mapper.update:
UPDATE DAILYLOOKS
SET IS_ACTIVE = 'N'
WHERE DAILYLOOK_ID = #{dailylookId}

mapper.select:
SELECT COUNT(*)
FROM DAILYLOOKS 
WHERE TO_CHAR(WEAR_DATE, 'YYYY-MM') = #{yearMonth} 
AND USER_ID = #{userId} 
AND IS_ACTIVE = 'Y'
